// GET /api/search/?q=… — server-side search for the header palette
// (assets/js/components/search-palette.js). The browser sends the query and
// receives a dozen ranked hits; it never downloads the index.
//
// This is the site's only dynamic route. The `.dynamic.ts` extension is
// registered in next.config.ts for the Vercel build only, so the static
// export used by the parity harness (which cannot contain a request-time
// handler) simply does not see this file.
//
// The index is generated by scripts/next/build-search-index.ts before every
// build and bundled here, so a request costs no file or network I/O. Content
// only changes with a deployment, which also purges the CDN, so responses are
// cached at the edge per query.
import index from "@/lib/generated/search-index.json";
import type { SearchDoc } from "@/lib/nonhtml";
import { createEngine, search } from "@/lib/search-engine";

const engine = createEngine(index as SearchDoc[]);

export function GET(request: Request) {
  const query = new URL(request.url).searchParams.get("q") ?? "";
  return Response.json(search(engine, query), {
    headers: {
      "Cache-Control": "public, max-age=300, s-maxage=86400, stale-while-revalidate=604800",
      "X-Robots-Tag": "noindex",
    },
  });
}
